<?php require "db.php";$pageTitle="Maintenance";$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$v=(int)($_POST["vehicle_id"]??0);$type=trim($_POST["service_type"]??"");$date=$_POST["service_date"]??"";$cost=(float)($_POST["cost"]??0);$notes=trim($_POST["notes"]??"");if($v&&$type&&$date){$s=$conn->prepare("INSERT INTO maintenance(vehicle_id,service_type,service_date,cost,notes) VALUES(?,?,?,?,?)");$s->bind_param("isdss",$v,$type,$date,$cost,$notes);$msg=$s->execute()?"Maintenance record saved.":"Could not save record.";}else $msg="Select a vehicle and complete service details.";} $vs=$conn->query("SELECT id,vehicle_number FROM vehicles ORDER BY vehicle_number");$list=$conn->query("SELECT m.*,v.vehicle_number FROM maintenance m JOIN vehicles v ON v.id=m.vehicle_id ORDER BY m.id DESC");include "includes/header.php";?><div class="page-head"><div><p class="eyebrow">SERVICE & UPKEEP</p><h1>Maintenance</h1><p>Record vehicle servicing and costs.</p></div></div><?php if($msg):?><p class="notice"><?=htmlspecialchars($msg)?></p><?php endif;?><section class="panel"><h2>Add maintenance record</h2><form method="post" class="form-grid"><label>Vehicle<select name="vehicle_id" required><option value="">Select vehicle</option><?php while($x=$vs->fetch_assoc()):?><option value="<?=$x["id"]?>"><?=htmlspecialchars($x["vehicle_number"])?></option><?php endwhile;?></select></label><label>Service type<input name="service_type" placeholder="Oil change / Repair" required></label><label>Service date<input type="date" name="service_date" required></label><label>Cost (₹)<input type="number" name="cost" min="0" step=".01" value="0"></label><label class="wide">Notes<textarea name="notes" rows="3"></textarea></label><button class="button">Save record</button></form></section><section class="panel"><h2>Maintenance history</h2><?php if($list&&$list->num_rows):?><div class="table-wrap"><table><tr><th>Vehicle</th><th>Service</th><th>Date</th><th>Cost</th><th>Notes</th></tr><?php while($x=$list->fetch_assoc()):?><tr><td><?=htmlspecialchars($x["vehicle_number"])?></td><td><?=htmlspecialchars($x["service_type"])?></td><td><?=$x["service_date"]?></td><td>₹<?=number_format((float)$x["cost"],2)?></td><td><?=htmlspecialchars($x["notes"])?></td></tr><?php endwhile;?></table></div><?php else:?><p class="muted">No maintenance records yet.</p><?php endif;?></section><?php include "includes/footer.php";?>